                out[r][c] = color
                holes.append((r, c, color))
    for r, c, color in holes:
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color
    bar_rows = [r for r, row in enumerate(grid) if sum(v != 0 for v in row) >= 4]
    if bar_rows:
        last_bar = max(bar_rows)
        for r in range(last_bar + 1, len(grid)):
            for c, color in enumerate(grid[r]):
                if color == 0:
                    continue
                for rr in range(r - 1, last_bar - 1, -1):
                    if out[rr][c] != 0:
                        break
                    out[rr][c] = color
    return out
